def test_no_rows_gives_no_rows() -> None:
    assert validate_rows([]) == []


def test_zero_and_negative_closes_are_dropped() -> None:
    rows = [
        RawRow(date="2024-03-01", ticker="ACME", close=0.0),
        RawRow(date="2024-03-04", ticker="ACME", close=-1.5),
        RawRow(date="2024-03-05", ticker="ACME", close=0.01),
    ]

    assert validate_rows(rows) == [RawRow(date="2024-03-05", ticker="ACME", close=0.01)]


def test_later_duplicate_in_file_order_wins() -> None:
    rows = [
        RawRow(date="2024-03-01", ticker="ACME", close=1.0),
        RawRow(date="2024-03-01", ticker="GLOBEX", close=5.0),
        RawRow(date="2024-03-01", ticker="ACME", close=2.0),
    ]

    assert validate_rows(rows) == [
        RawRow(date="2024-03-01", ticker="ACME", close=2.0),
        RawRow(date="2024-03-01", ticker="GLOBEX", close=5.0),
    ]


def test_unusable_later_duplicate_does_not_replace_usable_one() -> None:
    rows = [
        RawRow(date="2024-03-01", ticker="ACME", close=1.0),
        RawRow(date="2024-03-01", ticker="ACME", close=None),
    ]

    assert validate_rows(rows) == [RawRow(date="2024-03-01", ticker="ACME", close=1.0)]


def test_requested_ticker_without_usable_row_is_key_error_naming_it() -> None:
    rows = [
        RawRow(date="2024-03-01", ticker="ACME", close=1.0),
        RawRow(date="2024-03-01", ticker="GLOBEX", close=0.0),
    ]

    with pytest.raises(KeyError, match="GLOBEX") as excinfo:
        validate_rows(rows, ["ACME", "GLOBEX"])
    assert "ACME" not in str(excinfo.value)

